<?php $pageTitle='My Account';$theme='pink';require_once 'includes/user-auth.php';require_user();$u=user();$book=$pdo->prepare('SELECT * FROM bookings WHERE user_id=? ORDER BY id DESC');$book->execute([$u['id']]);$plans=$pdo->prepare('SELECT * FROM event_plans WHERE user_id=? ORDER BY id DESC');$plans->execute([$u['id']]);include 'includes/header.php';?><section class="py-5"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">CUSTOMER DASHBOARD</p><h2>Hello, <?=htmlspecialchars($u['name'])?></h2></div><a href="logout.php" class="btn btn-outline-dark">Logout</a></div><div class="row g-4"><div class="col-lg-6"><div class="content-card p-4"><h4>My Event Plans</h4><?php foreach($plans as $p):?><div class="border-bottom py-2"><b><?=htmlspecialchars($p['event_type'])?></b><div class="small text-muted"><?=htmlspecialchars($p['event_date'])?> · PKR <?=number_format($p['budget'])?></div></div><?php endforeach;if(!$plans):?><p class="text-muted">No saved plans yet.</p><?php endif;?></div></div><div class="col-lg-6"><div class="content-card p-4"><h4>My Bookings</h4><?php foreach($book as $b):?><div class="border-bottom py-2"><b><?=htmlspecialchars($b['booking_no'])?></b><div class="small text-muted"><?=htmlspecialchars($b['event_type'])?> · <?=htmlspecialchars($b['status'])?></div></div><?php endforeach;if(!$book):?><p class="text-muted">No bookings yet.</p><?php endif;?></div></div></div></div></section><?php include 'includes/footer.php';?>
